<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\{Course,CourseEnrolment,Lesson,YouthProfile}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CourseController extends Controller { public function index(Request $r){$q=Course::query()->where('is_published',true)->withCount('lessons'); if($r->user() && ($cat=YouthProfile::where('user_id',$r->user()->id)->value('age_category'))) $q->whereIn('age_category',['all',$cat]); return response()->json($q->latest()->paginate(12));} public function show(Course $course){abort_unless($course->is_published,404); return response()->json($course->load(['lessons'=>fn($q)=>$q->where('is_published',true)]));} public function enrol(Request $r,Course $course){$e=CourseEnrolment::firstOrCreate(['course_id'=>$course->id,'user_id'=>$r->user()->id]); return response()->json(['message'=>'Enrolled successfully.','enrolment'=>$e]);} public function completeLesson(Request $r,Lesson $lesson){abort_unless($lesson->is_published,404); DB::table('lesson_progress')->updateOrInsert(['lesson_id'=>$lesson->id,'user_id'=>$r->user()->id],['completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]); $course=$lesson->course; $total=max(1,$course->lessons()->where('is_published',true)->count()); $done=DB::table('lesson_progress')->where('user_id',$r->user()->id)->whereIn('lesson_id',$course->lessons()->where('is_published',true)->pluck('id'))->whereNotNull('completed_at')->count(); $pct=(int)round(($done/$total)*100); CourseEnrolment::updateOrCreate(['course_id'=>$course->id,'user_id'=>$r->user()->id],['progress_percent'=>$pct,'completed_at'=>$pct===100?now():null]); if($pct===100){ app(\App\Services\Certificates\CertificateService::class)->issue($course,$r->user()); } return response()->json(['message'=>'Lesson completed.','progress_percent'=>$pct]);}}